            cid: c || null,
            isVip: e==1 || false,
            isPay: f==1 || false,
            ccid: null,
            cbid: null
          })) : "",
        "ChapterInfo": d || "",
        "isVip": e==1 || false,
        "isPay": f==1 || false
    });
}


let t_List = $.Volumes;
