ruleContent.content:
@js: 
//获取章节正文真实链接
var u2 = result.match(/initTxt\("(.*?)"/)[1]
var bookurl = "https:"+u2
var book = java.ajax(bookurl)
//解码正文
function t(oE) {
    var oJ = oE['replace'];
    for (var ox in oJ) {
        var oa = new RegExp(oJ[ox], 'ig');
        oE['content'] = oE['content']['replace'](oa, ox);
    }
    return oE['content']
}
var f = book.replace("_txt_call(", "").replace(");", "").replace(")", "")
var g = f.match(/null/)
if (g) {
    var text = "获取正文失败！"
    text
} else {
    var z = eval("(" + f + ")")
    var text = t(z)
    text
}

