// SQ_LOCAL_EMOTION_TTS_BEGIN
function sqReadMode() {
  try {
    var rawVariable = String(source.getVariable() || "");
    var variableList = rawVariable ? JSON.parse(rawVariable) : [];
    var variableMode = String(variableList[0] && variableList[0].sqReadMode || "");
    if (variableMode == "听书") return "听书";
    if (variableMode == "小说") return "小说";
  } catch (eVariableMode) {}
  // The direct source value is written by the mode buttons and must win over
  // an older login-info snapshot retained by the reader.
  try {
    var storedMode = String(source.get("sqReadMode") || "");
    if (storedMode == "听书") return "听书";
    if (storedMode == "小说") return "小说";
  } catch (eStoredMode) {}
  try {
    var map = source.getLoginInfoMap();
    var loginMode = map && (map.get ? map.get("阅读模式") : map["阅读模式"]);
    if (String(loginMode || "") == "听书") return "听书";
    if (String(loginMode || "") == "小说") {
      try {
        if (String(source.get("sqReadModeUpdatedAt") || "")) return "小说";
      } catch (eLoginStamp) {}
    }
  } catch (eLoginMode) {}
  try {
    var directMode = String(source.get("sqReadMode") || "");
    if (directMode == "听书") return "听书";
    if (directMode == "小说" && String(source.get("sqReadModeUpdatedAt") || "")) return "小说";
  } catch (e) {}
  // A newly imported source has no mode yet. Start in audio mode so an old
  // cached text chapter cannot silently win before the first toggle.
  return "听书";
}

function sqTtsSorted(str, withKeys) {
  var obj = {};
  String(str || "").split("&").forEach(function (item) {
    var at = item.indexOf("=");
    var key = at < 0 ? item : item.substring(0, at);
    var value = at < 0 ? "" : item.substring(at + 1);
    obj[key] = value;
  });
  return Object.keys(obj).sort().map(function (key) {
    return withKeys ? key + "=" + obj[key] : obj[key];
  }).join(withKeys ? "&" : "");
}

function sqTtsSetting(name, fallback) {
  try {
    var map = source.getLoginInfoMap();
    var value = map && (map.get ? map.get(name) : map[name]);
    if (value !== null && value !== undefined && String(value).trim()) {
      return String(value).trim();
    }
  } catch (e) {}
  return fallback;
}

function sqTtsSpeaker() {
  try {
    var saved = String(source.get("sqTtsSpeaker") || "").trim();
    if (saved) return saved;
  } catch (eSaved) {}
  var custom = sqTtsSetting("自定义音色ID", "");
  if (custom) return custom;
  return "multi_role";
}

function sqTtsUserId() {
  var value = sqTtsSetting("userId", "12345678");
  return /^\d+$/.test(value) ? value : "12345678";
}

function SqTtsGetUrl(path, params, sourceUrl) {
  sourceUrl = sourceUrl || "https://ocean.shuqireader.com";
  var userId = sqTtsUserId();
  var timestamp = Math.floor(Date.now() / 1000);
  var body;
  var sign;
  if (/\/book\/info$/.test(path)) {
    var infoKey = "37e81a9d8f02596e1b895d07c171d5c9";
    var infoParams = "user_id=" + userId + "&timestamp=" + timestamp + "&" + params;
    sign = sqMd5(sqTtsSorted(infoParams, false) + infoKey);
    body = infoParams + "&platform=0&needFreeStack=1&sign=" + sign;
  } else {
    var gatewayKey = "eefc4798f28ea41622487ad80ef7e81c";
    var gatewayParams = "sqSv=1.0&user_id=" + userId + "&timestamp=" + timestamp +
      "&platform=0&" + params;
    sign = sqMd5(sqTtsSorted(gatewayParams, true) + "&skey=" + gatewayKey);
    body = gatewayParams + "&key=sq_h5_gateway&sign=" + sign;
  }
  return sourceUrl + path + "," + JSON.stringify({ method: "POST", body: body });
}

function sqTtsAudioUrl(bookId, chapterId) {
  var params = "bookId=" + bookId +
    "&chapterIds=" + chapterId +
    "&isDownload=0&getAllUrl=&appVer=12.6.5.263&rType=1&orderSpeakerList=" + sqTtsSpeaker();
  return SqTtsGetUrl("/api/bcspub/andapi/tts/download/v2", params);
}

// Catalog metadata is keyed by contUrlSuffix, but cached chapters use the
// complete content URL. Resolve either representation.
sqLookupChapterMap = function (map, url) {
  map = map || {};
  var raw = String(url || "");
  var optionAt = raw.lastIndexOf(",{");
  if (optionAt > 0) raw = raw.substring(0, optionAt);
  var candidates = [raw];
  var queryAt = raw.indexOf("?");
  if (queryAt >= 0) candidates.push(raw.substring(queryAt));
  for (var i = 0; i < candidates.length; i++) {
    if (Object.prototype.hasOwnProperty.call(map, candidates[i])) return map[candidates[i]];
  }
  try {
    var keys = Object.keys(map);
    for (var j = 0; j < keys.length; j++) {
      var key = String(keys[j] || "");
      if (key && raw.indexOf(key) >= 0) return map[keys[j]];
    }
  } catch (eSuffix) {}
  return null;
};
// SQ_LOCAL_EMOTION_TTS_END

var SQ_TTS_VOICE_REFRESHED = {};
function sqRefreshTtsVoices(currentBookId, force) {
  var id = String(currentBookId || "").trim();
  if (!id) return [];
  var storedId = "";
  var storedKeys = "";
  try {
    storedId = String(source.get("sqTtsVoiceBookId") || "").trim();
    storedKeys = String(source.get("sqTtsVoiceKeys") || "").trim();
  } catch (eStoredVoices) {}
  if (!force && storedId == id && storedKeys) {
    return storedKeys.split(",").filter(Boolean);
  }
  if (!force && SQ_TTS_VOICE_REFRESHED[id]) return [];
  SQ_TTS_VOICE_REFRESHED[id] = true;
  try {
    var raw = java.ajax(GetUrl("/webapi/bcspub/openapi/book/info", "bookId=" + id));
    var obj = JSON.parse(String(raw || "{}"));
    var data = obj && obj.data || {};
    var voices = Array.isArray(data.ttsSpeakerInfos) ? data.ttsSpeakerInfos :
      (data.bookInfo && Array.isArray(data.bookInfo.ttsSpeakerInfos) ? data.bookInfo.ttsSpeakerInfos : []);
    voices = voices.filter(function (v) { return String(v && v.speakerKey || "").trim(); });
    var keys = voices.map(function (v) { return String(v.speakerKey || "").trim(); });
    var names = voices.map(function (v) { return String(v.speakerName || v.speakerKey || "").trim(); });
    source.put("sqTtsVoiceBookId", id);
    source.put("sqTtsAvailable", keys.length ? "1" : "0");
    source.put("sqTtsVoiceKeys", keys.join(","));
    source.put("sqTtsVoiceNames", names.join("、"));
    return keys;
  } catch (eRefreshVoices) {
    return [];
  }
}

// Select a voice that the current book actually advertises. Composite or
// stale IDs such as multi_role must not be sent when the book exposes only
// individual speakers.
sqTtsSpeaker = function (currentBookId) {
  var selected = "";
  try { selected = String(source.get("sqTtsSpeaker") || "").trim(); } catch (eSelected) {}
  if (!selected) {
    try { selected = String(sqTtsSetting("自定义音色ID", "") || "").trim(); } catch (eCustom) {}
  }
  var hadExplicitSelection = !!selected;
  var refreshedKeys = sqRefreshTtsVoices(currentBookId);
  var rawKeys = "";
  try { rawKeys = String(source.get("sqTtsVoiceKeys") || "").trim(); } catch (eKeys) {}
  try {
    var voiceBookId = String(source.get("sqTtsVoiceBookId") || "").trim();
    if (currentBookId && voiceBookId && voiceBookId != String(currentBookId)) rawKeys = "";
  } catch (eVoiceBook) {}
  var keys = rawKeys ? rawKeys.split(",").map(function (key) { return String(key || "").trim(); }).filter(Boolean) : refreshedKeys;
  if (keys.length) {
    if (selected && keys.indexOf(selected) >= 0) return selected;
    var fallback = keys[0];
    try {
      source.put("sqTtsSpeaker", fallback);
      var noticeKey = "sqTtsToneFallbackNotice";
      var lastNotice = String(source.get(noticeKey) || "");
      var currentNotice = String(currentBookId || "") + ":" + fallback;
      if (lastNotice != currentNotice) {
        var names = String(source.get("sqTtsVoiceNames") || "").split("、");
        var fallbackName = names[0] || fallback;
        java.longToast((hadExplicitSelection ? "当前音色不存在或本书不支持" : "未设置听书音色") +
          "，已自动切换为本书第一个支持音色：" + fallbackName);
        source.put(noticeKey, currentNotice);
      }
    } catch (eFallback) {}
    return fallback;
  }
  return selected || "multi_role";
};
sqTtsAudioUrl = function (bookId, chapterId, speaker) {
  var actualSpeaker = String(speaker || "").trim() || sqTtsSpeaker(String(bookId));
  var params = "bookId=" + bookId +
    "&chapterIds=" + chapterId +
    "&isDownload=0&getAllUrl=&appVer=12.6.5.263&rType=1&orderSpeakerList=" + actualSpeaker;
  return SqTtsGetUrl("/api/bcspub/andapi/tts/download/v2", params);
};

