@js:var doc = org.jsoup.Jsoup.parse(result);
// 定位下一页按钮：.hl-page-wrap 内，文本含“下一页”的a标签（匹配实际HTML结构）
var nextLinkElem = doc.select("ul.hl-page-wrap a:contains(下一页)").first();

if (!nextLinkElem) {
    // 没找到下一页按钮，返回空
    "";
} else {
    var nextUrl = nextLinkElem.attr("href");
    // 按“-数字/”提取页码（如/arttype/5-2/里的2，匹配实际URL格式）
    var pageMatch = nextUrl.match(/-(\d+)\/$/);

    if (!pageMatch) {
        // 页码格式不对，返回空
        "";
    } else {
        var nextPage = parseInt(pageMatch[1], 10);
        // 下一页页码≤10则返回链接，否则停止（保留原逻辑）
        nextPage <= 10 ? nextUrl : "";
    }
}

